#!/bin/bash
# AI DISCLAIMER: All of the text in this file was generated by AI.
# BP+ split, one replay run on box5600g (Ryzen 5 5600G, 6 cores / 12 threads), all threads, no --max-concurrency.
# The blocks come from a stock source node on another machine on the LAN (SRC=<host:port>, given by the caller), so the
# start DB stressnet_h3103300c (restored into ~/work/chains/stressnet by the control box) is the only DB here.
# The hash at END is checked against EXPECT (the hash box3900x's replays recorded). Samples as bpp_run.sh.
# usage: SRC=<host:port> EXPECT=<hash> [END=<height>] bpp_run_5600g.sh <name> <monerod>    Marker BPP_RUN_DONE in run.log.
set -u
name=$1; BIN=$2
W=$HOME/work/bppall; O=$W/runs/$name; DD=$HOME/work/chains/stressnet
END=${END:-3103500}; RUN_TIMEOUT=${RUN_TIMEOUT:-7200}
[ -x "$BIN" ] && [ -n "${SRC:-}" ] && [ -n "${EXPECT:-}" ] && [ -f "$DD/testnet/lmdb/data.mdb" ] || { echo "ABORT: missing binary, SRC, EXPECT or DB"; exit 1; }
[ -e "$O" ] && { echo "ABORT: $O exists"; exit 1; }
mkdir -p $O; L=$O/run.log
log() { echo "$(date -u +%FT%TZ) $*" >> $L; }
GOV0=$(cat /sys/devices/system/cpu/cpu0/cpufreq/scaling_governor)
fin() { sudo cpupower -c all frequency-set -g $GOV0 > /dev/null 2>&1; log "governor back to $(cat /sys/devices/system/cpu/cpu0/cpufreq/scaling_governor)"; log "BPP_RUN_DONE $1"; exit 0; }
log "start $name; binary $(sha256sum $BIN | cut -c1-16) $($BIN --version | tail -1); end $END"
pgrep -u $USER -x monerod > /dev/null && { log "ABORT a monerod is running"; fin abort; }
pgrep -x shadow > /dev/null && { log "ABORT shadow lanes are running"; fin abort; }
# wait up to 300 s for the load to settle (the restore's writeback and the previous run raise it); abort if it does not
for i in $(seq 1 60); do l1=$(cut -d' ' -f1 /proc/loadavg); awk -v l=$l1 'BEGIN{exit !(l > 1.5)}' || break; sleep 5; done
log "load $(cut -d' ' -f1-3 /proc/loadavg) (waited $(( (i - 1) * 5 )) s); users $(who | wc -l); free GB $(df --output=avail -BG $HOME | tail -1); top CPU users: $(ps -eo user,pcpu --sort=-pcpu --no-headers | head -3 | tr -s ' ' | tr '\n' ';')"
awk -v l=$l1 'BEGIN{exit !(l > 1.5)}' && { log "ABORT the box is busy (load $l1 after 300 s)"; fin abort; }
rm -f $DD/testnet/lmdb/lock.mdb
sync; sudo sysctl -q vm.drop_caches=3
sudo cpupower -c all frequency-set -g performance > /dev/null && log "governor $GOV0 -> performance"
t0=$(date +%s)
(setsid nohup $BIN --testnet --data-dir $DD --add-exclusive-node $SRC --p2p-bind-ip 127.0.0.1 --no-igd --no-zmq \
  --non-interactive --rpc-bind-ip 127.0.0.1 --rpc-bind-port 28081 --show-time-stats 1 \
  --log-file $O/node.log --log-level 0,blockchain:INFO > $O/node.stdout 2>&1 &)
NP=; for i in $(seq 1 120); do NP=$(pgrep -u $USER -f "^$BIN --testnet --data-dir $DD " | head -1); [ -n "$NP" ] && break; sleep 0.5; done
[ -n "$NP" ] || { log "ABORT the test node did not start"; fin abort; }
log "test node pid $NP; affinity $(taskset -pc $NP 2>&1 | sed 's/.*: //')"
pidstat -t -u -p $NP 2 > $O/pidstat.txt 2>&1 &
PS=$!
echo "unix_s,height,ticks" > $O/samples.csv
( while kill -0 $NP 2>/dev/null; do
    hh=$(curl -s -m 2 http://127.0.0.1:28081/get_height | grep -oE '"height": [0-9]+' | grep -oE '[0-9]+$')
    tk=$(awk '{print $14 + $15}' /proc/$NP/stat 2>/dev/null)
    echo "$(date +%s.%N),${hh:-},${tk:-}" >> $O/samples.csv
    sleep 1
  done ) &
SP=$!
h=0; why=timeout
while [ $(( $(date +%s) - t0 )) -lt $RUN_TIMEOUT ]; do
  sleep 5
  kill -0 $NP 2>/dev/null || { why=exited; break; }
  h=$(curl -s -m 5 http://127.0.0.1:28081/get_height | grep -oE '"height": [0-9]+' | grep -oE '[0-9]+$'); h=${h:-0}
  [ "$h" -gt $END ] && { why=end; break; }
done
log "end: $why at height $h after $(( $(date +%s) - t0 )) s from launch"
top=$(curl -s -m 10 http://127.0.0.1:28081/json_rpc -d '{"jsonrpc":"2.0","id":0,"method":"get_block_header_by_height","params":{"height":'$END'}}' | grep -oE '"hash": "[0-9a-f]+"' | head -1 | cut -d'"' -f4)
log "block $END: node $top expected $EXPECT $([ -n "$top" ] && [ "$top" = "$EXPECT" ] && echo HASH_OK || echo HASH_BAD)"
curl -s -m 30 http://127.0.0.1:28081/stop_daemon > /dev/null
for i in $(seq 1 300); do kill -0 $NP 2>/dev/null || break; sleep 1; done
kill -0 $NP 2>/dev/null && { log "test node still up, TERM"; kill -TERM $NP; sleep 30; }
kill $SP $PS 2>/dev/null; wait $SP $PS 2>/dev/null
log "monerod processes left: $(pgrep -u $USER -x monerod | wc -l)"
rm -f $DD/testnet/lmdb/lock.mdb
log "node log: ERROR $(grep -c '	ERROR	' $O/node.log), time-stats lines $(grep -c 'p/t:' $O/node.log)"
fin $why
